#ifndef TROUPE_ART_DRIVER_H
#define TROUPE_ART_DRIVER_H

#include <ResidentDriver.h>
#include <ResidentLuaModule.h>

// Resident driver serving the troupe's resident sprite art from flash
// (TroupeArtData.h, generated by tools/gen-troupe-header.ts).
// Lua API: troupe.fingerprint()      -> 8-hex crc32 of the resident art set
//          troupe.install(S, ids)    -> S.palette + S.sprites[id] per id
// Behavior is mirrored by emitTroupeStubLua for headless tests — keep the
// two in lockstep.
class TroupeArtDriver : public Resident::Driver {
 public:
  const char* name() const override { return "troupe"; }
  void registerModule(Resident::LuaModule& m) override {
    m.method<TroupeArtDriver, &TroupeArtDriver::install>("install")
        .method<TroupeArtDriver, &TroupeArtDriver::fingerprint>("fingerprint");
  }

  int install(lua_State* L);
  int fingerprint(lua_State* L);
};

#endif  // TROUPE_ART_DRIVER_H
